    const cameraTarget = new THREE.Vector3(0, 3.05, 0);
    const spherical = new THREE.Spherical(10.8, 1.08, 0.72);
    const initialCamera = {
      target: cameraTarget.clone(),
      spherical: spherical.clone()
    };

    let autoOrbit = false;
    let paused = false;
    let xrayEnabled = true;

    const pointers = new Map();
    let dragMode = "orbit";
    let previousPointer = { x: 0, y: 0 };
    let previousPinchDistance = 0;

    function updateCamera() {
      camera.position.setFromSpherical(spherical).add(cameraTarget);
      camera.lookAt(cameraTarget);
    }

    function resetCamera() {
      cameraTarget.copy(initialCamera.target);
      spherical.copy(initialCamera.spherical);
      updateCamera();
    }

    function panCamera(deltaX, deltaY) {
      const right = new THREE.Vector3().setFromMatrixColumn(
        camera.matrix,
        0
      );
      const up = new THREE.Vector3().setFromMatrixColumn(
        camera.matrix,
        1
      );
      const scale = spherical.radius * 0.00125;

      cameraTarget.addScaledVector(right, -deltaX * scale);
      cameraTarget.addScaledVector(up, deltaY * scale);

      cameraTarget.y = THREE.MathUtils.clamp(cameraTarget.y, 0.8, 6.2);
      updateCamera();
    }

    canvas.addEventListener("contextmenu", (event) => {
