      } else if (event.key === "ArrowRight") {
        spherical.theta -= 0.08;
      } else if (event.key === "ArrowUp") {
        spherical.phi = Math.max(0.22, spherical.phi - 0.06);
      } else if (event.key === "ArrowDown") {
        spherical.phi = Math.min(1.48, spherical.phi + 0.06);
      } else if (event.key === "+" || event.key === "=") {
        spherical.radius = Math.max(5.2, spherical.radius - 0.4);
      } else if (event.key === "-") {
        spherical.radius = Math.min(19, spherical.radius + 0.4);
      } else {
