    // ---------------------------------------------------------------------
    // Animation
    // ---------------------------------------------------------------------

    let stageCounter = 0;

    function updateStage() {
      const kelvin = currentTemperature;
      let stage;

      if (kelvin < 0.1) {
        stage = "mK regime • dilute phase";
        stageCounter = 18;
      } else if (kelvin < 1) {
        stage = "mmK regime • nuclear freeze";
        stageCounter = 17;
      } else if (kelvin < 4) {
        stage = "Superfluid transition";
        stageCounter = 16;
      } else if (kelvin < 20) {
        stage = "Low-temperature plate stack";
        stageCounter = 15;
      } else {
        stage = "Warm-up / vacuum pre-conditioning";
        stageCounter = 1;
      }

      if (stage !== previousStage) {
        stageValue.textContent = stage;
        stageIndex.textContent = `Stage ${String(stageCounter).padStart(2, "0")}`;
        previousStage = stage;
      }
    }

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      const time = clock.elapsedTime;

      if (!paused) {
        currentTemperature +=
          (targetTemperature - currentTemperature) *
          (1 - Math.exp(-delta * 0.24));

        if (Math.abs(targetTemperature - currentTemperature) < 0.01) {
          currentTemperature = targetTemperature;
        }

        updateStage();

        const setpointMillikelvin = Number(temperatureSlider.value);
        tempValue.textContent = currentTemperature.toFixed(2);

        const kelvin = 300 - setpointMillikelvin * 2.86;
        tempValue.textContent = currentTemperature.toFixed(2);

        const progress = THREE.MathUtils.clamp(
          (300 - currentTemperature) / 300,
          0,
          1
        );

        progressFill.style.width = `${progress * 100}%`;
      }

      if (autoOrbit) {
        spherical.theta += delta * 0.13;
        updateCamera();
      }

      const ringOffset = (time * 0.36 + stageCounter * 0.47) % 4.2;

      coolingRings.forEach((ring, index) => {
        ring.position.y = 1.25 + ringOffset + index * 1.45;
        ring.material.opacity =
          0.22 * Math.exp(-((ringOffset + index * 1.45) / 1.45));
      });

      materials.cyanGlow.emissiveIntensity =
        1.8 + Math.sin(time * 2.2) * 0.35;

      materials.redGlow.emissiveIntensity =
        2.0 + Math.sin(time * 3.1 + 1.2) * 0.3;

      updateLabels();
      renderer.render(scene, camera);
    }

    function resize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight, false);
    }

    window.addEventListener("resize", resize);

    updateCamera();
    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      $("loading").classList.add("hide");
    });
  </script>
</body>
